<?php
namespace Delnavazan\Platform\Core\Application; use Delnavazan\Platform\Core\Infrastructure\Repository\{InstrumentRepository,CourseRepository};
final class CatalogueService { public function instrument(array $d):int{if(!current_user_can('dzn_manage_courses'))throw new \RuntimeException('Unauthorized');$d['slug']=sanitize_title($d['slug']??'');$d['name_fa']=Normalizer::text($d['name_fa']??null);$d['name_en']=Normalizer::text($d['name_en']??null);if(!$d['slug']||(!$d['name_fa']&&!$d['name_en']))throw new \InvalidArgumentException('Slug and Instrument name required');$d['status']=Normalizer::one($d['status']??'active',['active','inactive'],'instrument state');return Creator::create(new InstrumentRepository,$d,'DZN-INS-');} public function course(array $d):int{if(!current_user_can('dzn_manage_courses'))throw new \RuntimeException('Unauthorized');$d['instrument_id']=Normalizer::id($d['instrument_id']??null);if(!(new InstrumentRepository)->usable($d['instrument_id']))throw new \InvalidArgumentException('Usable Instrument required');$d['name_fa']=Normalizer::text($d['name_fa']??'',191,true);$d['name_en']=Normalizer::text($d['name_en']??'',191,true);$d['course_type']=Normalizer::one($d['course_type']??'',['standard','introductory'],'course type');$d['status']=Normalizer::one($d['status']??'active',['active','inactive'],'course state');$d['default_duration_minutes']=Normalizer::count($d['default_duration_minutes']??0,5,480);$d['default_buffer_minutes']=Normalizer::count($d['default_buffer_minutes']??0,0,240);return Creator::create(new CourseRepository,$d,'DZN-CRS-');} }
